// An event is generally an action. Action may be taken by the user or system. 
// The user or the system will perform some action, and after that, we have to perform some action.
// This is called event handling.
// We have two types of events: one is a system-generated event, and the other is a user-generated event.
// For example, the loading of a web page is a system-generated event. After loading, we have to show some data on the web page generated by the user.


import React from 'react';
function FunctionalComponent() {
  const handleClick = () => {
    alert('Button clicked!');
  };
  return (
    <button onClick={handleClick}>Click Me</button>
    // <button onClick={() => handleClick()}>Click Me</button> // with arrow function . cross check it is calling is write or not .
  );
}
export default FunctionalComponent;
